window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-d51dfd685e9cba57"]={"versions": [{"id": "FIG-d51dfd685e9cba57", "releases": ["R18-03_R1.4.0"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Objektdiagramm (Instanzbeispiel) zur Manifest-Spezifikation der AUTOSAR Adaptive Platform. Das Diagramm illustriert das Metamodell-Mapping zwischen einem anwendungsseitigen eindimensionalen Array-Datentyp (<code>ApplicationDataType</code>) und seiner C++-spezifischen Implementierungsausprägung (<code>CppImplementationDataType</code>).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Dargestellt sind sieben Instanzen und deren Assoziationen:</p>\n<ul class=\"fig-list\"><li><code>DataTypeMapping :DataTypeMap</code>: Zentrales Mapping-Objekt, referenziert über Rolle <code>+applicationDataType</code> auf <code>ArrayLinear</code> und über <code>+implementationDataType</code> auf <code>ArrayLinearImpl</code>.\n</li><li><code>ArrayLinear : ApplicationArrayDataType</code>: Kategorie <code>category = ARRAY</code>, aggregiert über Komposition mit Rolle <code>+element</code> die Instanz <code>ArrayElementLinear</code>.\n</li><li><code>ArrayElementLinear : ApplicationArrayElement</code>: Eigenschaften <code>category = VALUE</code>, <code>maxNumberOfElements = 5</code>, <code>arraySizeSemantics = fixedSize</code>. Referenziert über Assoziation <code>+type</code> den Elementtyp <code>ArrayLinearElementDataType</code>.\n</li><li><code>ArrayLinearElementDataType : ApplicationPrimitiveDataType</code>: Kategorie <code>category = VALUE</code>.\n</li><li><code>ArrayLinearImpl : CppImplementationDataType</code>: Eigenschaften <code>arraySize = 5</code>, <code>category = ARRAY</code>. Aggregiert über Komposition mit Rolle <code>+templateArgument</code> das Template-Argument <code>:CppTemplateArgument</code>.\n</li><li><code>:CppTemplateArgument</code>: Anonyme Instanz mit Attributwerten <code>anonymous = True</code> und <code>isVariadicTemplate = False</code>. Referenziert über Assoziation <code>+templateType</code> den Typ <code>uint16</code>.\n</li><li><code>uint16 : CppImplementationDataType</code>: Kategorie <code>category = VALUE</code>.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Strukturmodell ohne dynamische Ablauf- oder Sequenzpfade. Es beschreibt die deklarative Zuordnung und Strukturkonsistenz bei der Modellierung von Festgrößen-Arrays (Größe 5) von der Anwendungsebene auf die Template-basierte C++-Implementierungsebene.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Veranschaulicht die Modellierungsregeln für Arrays mit C++-Bindung:</p>\n<ul class=\"fig-list\"><li>Ein <code>ApplicationArrayDataType</code> mit <code>fixedSize</code> und <code>maxNumberOfElements = 5</code> korrespondiert mit einem <code>CppImplementationDataType</code> der Kategorie <code>ARRAY</code> mit <code>arraySize = 5</code>.\n</li><li>Der Elementtyp des C++-Arrays wird über die Komposition <code>+templateArgument</code> zu <code>CppTemplateArgument</code> und dessen Assoziation <code>+templateType</code> auf einen primitiven Implementierungsdatentyp (<code>uint16</code>) modelliert.\n</li><li>Das <code>DataTypeMap</code>-Element verbindet beide Repräsentationen eindeutig für Code-Generatoren und Modellvalidierungswerkzeuge.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-06cebc379baf7e0a", "releases": ["R18-10-1", "R18-10_R4.4.0_R1.5.0"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Objektdiagramm (Instanzbeispiel) zur Manifest-Spezifikation der AUTOSAR Adaptive Platform. Das Diagramm illustriert das Metamodell-Mapping zwischen einem anwendungsseitigen eindimensionalen Array-Datentyp (<code>ApplicationDataType</code>) und seiner C++-spezifischen Standard-Implementierungsausprägung (<code>StdCppImplementationDataType</code>).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Dargestellt sind sieben Instanzen und deren Assoziationen:</p>\n<ul class=\"fig-list\"><li><code>DataTypeMapping: DataTypeMap</code>: Zentrales Mapping-Objekt, referenziert über Rolle <code>+applicationDataType</code> auf <code>ArrayLinear</code> und über <code>+implementationDataType</code> auf <code>ArrayLinearImpl</code>.\n</li><li><code>ArrayLinear: ApplicationArrayDataType</code>: Kategorie <code>category = ARRAY</code>, aggregiert über Komposition mit Rolle <code>+element</code> die Instanz <code>ArrayElementLinear</code>.\n</li><li><code>ArrayElementLinear: ApplicationArrayElement</code>: Eigenschaften <code>category = VALUE</code>, <code>maxNumberOfElements = 5</code>, <code>arraySizeSemantics = fixedSize</code>. Referenziert über Assoziation <code>+type</code> den Elementtyp <code>ArrayLinearElementDataType</code>.\n</li><li><code>ArrayLinearElementDataType: ApplicationPrimitiveDataType</code>: Kategorie <code>category = VALUE</code>.\n</li><li><code>ArrayLinearImpl: StdCppImplementationDataType</code>: Eigenschaften <code>arraySize = 5</code>, <code>category = ARRAY</code>. Aggregiert über Komposition mit Rolle <code>+templateArgument</code> das Template-Argument <code>:CppTemplateArgument</code>.\n</li><li><code>:CppTemplateArgument</code>: Anonyme Instanz mit Attributwert <code>isVariadicTemplate = False</code>. Referenziert über Assoziation <code>+templateType</code> den Typ <code>uint16_t</code>.\n</li><li><code>uint16_t: StdCppImplementationDataType</code>: Kategorie <code>category = VALUE</code>.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Strukturmodell ohne dynamische Ablauf- oder Sequenzpfade. Es beschreibt die deklarative Zuordnung und Strukturkonsistenz bei der Modellierung von Festgrößen-Arrays (Größe 5) von der Anwendungsebene auf die Template-basierte C++-Implementierungsebene.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Veranschaulicht die Modellierungsregeln für Arrays mit C++-Standardbibliothek-Bindung (<code>std::array</code>):</p>\n<ul class=\"fig-list\"><li>Ein <code>ApplicationArrayDataType</code> mit <code>fixedSize</code> und <code>maxNumberOfElements = 5</code> korrespondiert mit einem <code>StdCppImplementationDataType</code> der Kategorie <code>ARRAY</code> mit <code>arraySize = 5</code>.\n</li><li>Der Elementtyp des C++-Arrays wird über die Komposition <code>+templateArgument</code> zu <code>CppTemplateArgument</code> und dessen Assoziation <code>+templateType</code> auf einen Standard-Implementierungsdatentyp (<code>uint16_t</code>) modelliert.\n</li><li>Das <code>DataTypeMap</code>-Element verbindet beide Repräsentationen eindeutig für Code-Generatoren und Modellvalidierungswerkzeuge.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-43a72dca760c910c", "releases": ["R19-03", "R19-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Objektdiagramm (Instanzbeispiel) zur Manifest-Spezifikation der AUTOSAR Adaptive Platform. Das Diagramm illustriert das Metamodell-Mapping zwischen einem anwendungsseitigen eindimensionalen Array-Datentyp (<code>ApplicationDataType</code>) und seiner C++-spezifischen Standard-Implementierungsausprägung (<code>StdCppImplementationDataType</code>).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Dargestellt sind sieben Instanzen und deren Assoziationen:</p>\n<ul class=\"fig-list\"><li><code>DataTypeMapping: DataTypeMap</code>: Zentrales Mapping-Objekt, referenziert über Rolle <code>+applicationDataType</code> auf <code>ArrayLinear</code> und über <code>+implementationDataType</code> auf <code>ArrayLinearImpl</code>.\n</li><li><code>ArrayLinear: ApplicationArrayDataType</code>: Kategorie <code>category = ARRAY</code>, aggregiert über Komposition mit Rolle <code>+element</code> die Instanz <code>ArrayElementLinear</code>.\n</li><li><code>ArrayElementLinear: ApplicationArrayElement</code>: Eigenschaften <code>category = VALUE</code>, <code>maxNumberOfElements = 5</code>, <code>arraySizeSemantics = fixedSize</code>. Referenziert über Assoziation <code>+type</code> den Elementtyp <code>ArrayLinearElementDataType</code>.\n</li><li><code>ArrayLinearElementDataType: ApplicationPrimitiveDataType</code>: Kategorie <code>category = VALUE</code>.\n</li><li><code>ArrayLinearImpl: StdCppImplementationDataType</code>: Eigenschaften <code>arraySize = 5</code>, <code>category = ARRAY</code>. Aggregiert über Komposition mit Rolle <code>+templateArgument</code> das Template-Argument <code>:CppTemplateArgument</code>.\n</li><li><code>:CppTemplateArgument</code>: Anonyme Instanz ohne Attributwerte. Referenziert über Assoziation <code>+templateType</code> den Typ <code>uint16_t</code>.\n</li><li><code>uint16_t: StdCppImplementationDataType</code>: Kategorie <code>category = VALUE</code>.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Strukturmodell ohne dynamische Ablauf- oder Sequenzpfade. Es beschreibt die deklarative Zuordnung und Strukturkonsistenz bei der Modellierung von Festgrößen-Arrays (Größe 5) von der Anwendungsebene auf die Template-basierte C++-Implementierungsebene.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Veranschaulicht die Modellierungsregeln für Arrays mit C++-Standardbibliothek-Bindung (<code>std::array</code>):</p>\n<ul class=\"fig-list\"><li>Ein <code>ApplicationArrayDataType</code> mit <code>fixedSize</code> und <code>maxNumberOfElements = 5</code> korrespondiert mit einem <code>StdCppImplementationDataType</code> der Kategorie <code>ARRAY</code> mit <code>arraySize = 5</code>.\n</li><li>Der Elementtyp des C++-Arrays wird über die Komposition <code>+templateArgument</code> zu <code>CppTemplateArgument</code> und dessen Assoziation <code>+templateType</code> auf einen Standard-Implementierungsdatentyp (<code>uint16_t</code>) modelliert.\n</li><li>Das <code>DataTypeMap</code>-Element verbindet beide Repräsentationen eindeutig für Code-Generatoren und Modellvalidierungswerkzeuge.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-802884da0f61df18", "releases": ["R20-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Objektdiagramm (Instanzbeispiel) zur Manifest-Spezifikation der AUTOSAR Adaptive Platform. Das Diagramm illustriert das Metamodell-Mapping zwischen einem anwendungsseitigen eindimensionalen Array-Datentyp (<code>ApplicationDataType</code>) und seiner C++-spezifischen Standard-Implementierungsausprägung (<code>StdCppImplementationDataType</code>).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Dargestellt sind sieben Instanzen und deren Assoziationen:</p>\n<ul class=\"fig-list\"><li><code>DataTypeMapping: DataTypeMap</code>: Zentrales Mapping-Objekt, referenziert über Rolle <code>+applicationDataType</code> auf <code>ArrayLinear</code> und über <code>+implementationDataType</code> auf <code>ArrayLinearImpl</code>.\n</li><li><code>ArrayLinear: ApplicationArrayDataType</code>: Kategorie <code>category = ARRAY</code>, aggregiert über Komposition mit Rolle <code>+element</code> die Instanz <code>ArrayElementLinear</code>.\n</li><li><code>ArrayElementLinear: ApplicationArrayElement</code>: Eigenschaften <code>category = VALUE</code>, <code>maxNumberOfElements = 5</code>, <code>arraySizeSemantics = fixedSize</code>. Referenziert über Assoziation <code>+type</code> den Elementtyp <code>ArrayLinearElementDataType</code>.\n</li><li><code>ArrayLinearElementDataType: ApplicationPrimitiveDataType</code>: Kategorie <code>category = VALUE</code>.\n</li><li><code>ArrayLinearImpl: StdCppImplementationDataType</code>: Eigenschaften <code>arraySize = 5</code>, <code>category = ARRAY</code>. Aggregiert über Komposition mit Rolle <code>+templateArgument</code> das Template-Argument <code>:CppTemplateArgument</code>.\n</li><li><code>:CppTemplateArgument</code>: Anonyme Instanz ohne Attributwerte. Referenziert über Assoziation <code>+templateType</code> den Typ <code>uint16_t</code>.\n</li><li><code>uint16_t: StdCppImplementationDataType</code>: Kategorie <code>category = VALUE</code>.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Strukturmodell ohne dynamische Ablauf- oder Sequenzpfade. Es beschreibt die deklarative Zuordnung und Strukturkonsistenz bei der Modellierung von Festgrößen-Arrays (Größe 5) von der Anwendungsebene auf die Template-basierte C++-Implementierungsebene.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Veranschaulicht die Modellierungsregeln für Arrays mit C++-Standardbibliothek-Bindung (<code>std::array</code>):</p>\n<ul class=\"fig-list\"><li>Ein <code>ApplicationArrayDataType</code> mit <code>fixedSize</code> und <code>maxNumberOfElements = 5</code> korrespondiert mit einem <code>StdCppImplementationDataType</code> der Kategorie <code>ARRAY</code> mit <code>arraySize = 5</code>.\n</li><li>Der Elementtyp des C++-Arrays wird über die Komposition <code>+templateArgument</code> zu <code>CppTemplateArgument</code> und dessen Assoziation <code>+templateType</code> auf einen Standard-Implementierungsdatentyp (<code>uint16_t</code>) modelliert.\n</li><li>Das <code>DataTypeMap</code>-Element verbindet beide Repräsentationen eindeutig für Code-Generatoren und Modellvalidierungswerkzeuge.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-5d79190f57ee2510", "releases": ["R21-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Objektdiagramm (Instanzbeispiel) zur Manifest-Spezifikation der AUTOSAR Adaptive Platform. Das Diagramm illustriert das Metamodell-Mapping zwischen einem anwendungsseitigen eindimensionalen Array-Datentyp (<code>ApplicationDataType</code>) und seiner C++-spezifischen Standard-Implementierungsausprägung (<code>StdCppImplementationDataType</code>).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Dargestellt sind sieben Instanzen und deren Assoziationen:</p>\n<ul class=\"fig-list\"><li><code>DataTypeMapping: DataTypeMap</code>: Zentrales Mapping-Objekt, referenziert über Rolle <code>+applicationDataType</code> auf <code>ArrayLinear</code> und über <code>+implementationDataType</code> auf <code>ArrayLinearImpl</code>.\n</li><li><code>ArrayLinear: ApplicationArrayDataType</code>: Kategorie <code>category = ARRAY</code>, aggregiert über Komposition mit Rolle <code>+element</code> die Instanz <code>ArrayElementLinear</code>.\n</li><li><code>ArrayElementLinear: ApplicationArrayElement</code>: Eigenschaften <code>category = VALUE</code>, <code>maxNumberOfElements = 5</code>, <code>arraySizeSemantics = fixedSize</code>. Referenziert über Assoziation <code>+type</code> den Elementtyp <code>ArrayLinearElementDataType</code>.\n</li><li><code>ArrayLinearElementDataType: ApplicationPrimitiveDataType</code>: Kategorie <code>category = VALUE</code>.\n</li><li><code>ArrayLinearImpl: StdCppImplementationDataType</code>: Eigenschaften <code>arraySize = 5</code>, <code>category = ARRAY</code>. Aggregiert über Komposition mit Rolle <code>+templateArgument</code> das Template-Argument <code>:CppTemplateArgument</code>.\n</li><li><code>:CppTemplateArgument</code>: Anonyme Instanz ohne Attributwerte. Referenziert über Assoziation <code>+templateType</code> den Typ <code>uint16_t</code>.\n</li><li><code>uint16_t: StdCppImplementationDataType</code>: Kategorie <code>category = VALUE</code>.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Strukturmodell ohne dynamische Ablauf- oder Sequenzpfade. Es beschreibt die deklarative Zuordnung und Strukturkonsistenz bei der Modellierung von Festgrößen-Arrays (Größe 5) von der Anwendungsebene auf die Template-basierte C++-Implementierungsebene.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Veranschaulicht die Modellierungsregeln für Arrays mit C++-Standardbibliothek-Bindung (<code>std::array</code>):</p>\n<ul class=\"fig-list\"><li>Ein <code>ApplicationArrayDataType</code> mit <code>fixedSize</code> und <code>maxNumberOfElements = 5</code> korrespondiert mit einem <code>StdCppImplementationDataType</code> der Kategorie <code>ARRAY</code> mit <code>arraySize = 5</code>.\n</li><li>Der Elementtyp des C++-Arrays wird über die Komposition <code>+templateArgument</code> zu <code>CppTemplateArgument</code> und dessen Assoziation <code>+templateType</code> auf einen Standard-Implementierungsdatentyp (<code>uint16_t</code>) modelliert.\n</li><li>Das <code>DataTypeMap</code>-Element verbindet beide Repräsentationen eindeutig für Code-Generatoren und Modellvalidierungswerkzeuge.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-3589afe62107d44a", "releases": ["R22-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Objektdiagramm (Instanzbeispiel) zur Manifest-Spezifikation der AUTOSAR Adaptive Platform. Das Diagramm illustriert das Metamodell-Mapping zwischen einem anwendungsseitigen eindimensionalen Array-Datentyp (<code>ApplicationDataType</code>) und seiner C++-spezifischen Standard-Implementierungsausprägung (<code>StdCppImplementationDataType</code>).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Dargestellt sind sieben Instanzen und deren Assoziationen:</p>\n<ul class=\"fig-list\"><li><code>DataTypeMapping: DataTypeMap</code>: Zentrales Mapping-Objekt, referenziert über Rolle <code>+applicationDataType</code> auf <code>ArrayLinear</code> und über <code>+implementationDataType</code> auf <code>ArrayLinearImpl</code>.\n</li><li><code>ArrayLinear: ApplicationArrayDataType</code>: Kategorie <code>category = ARRAY</code>, aggregiert über Komposition mit Rolle <code>+element</code> die Instanz <code>ArrayElementLinear</code>.\n</li><li><code>ArrayElementLinear: ApplicationArrayElement</code>: Eigenschaften <code>category = VALUE</code>, <code>maxNumberOfElements = 5</code>, <code>arraySizeSemantics = fixedSize</code>. Referenziert über Assoziation <code>+type</code> den Elementtyp <code>ArrayLinearElementDataType</code>.\n</li><li><code>ArrayLinearElementDataType: ApplicationPrimitiveDataType</code>: Kategorie <code>category = VALUE</code>.\n</li><li><code>ArrayLinearImpl: StdCppImplementationDataType</code>: Eigenschaften <code>arraySize = 5</code>, <code>category = ARRAY</code>. Aggregiert über Komposition mit Rolle <code>+templateArgument</code> das Template-Argument <code>:CppTemplateArgument</code>.\n</li><li><code>:CppTemplateArgument</code>: Anonyme Instanz ohne Attributwerte. Referenziert über Assoziation <code>+templateType</code> den Typ <code>uint16_t</code>.\n</li><li><code>uint16_t: StdCppImplementationDataType</code>: Kategorie <code>category = VALUE</code>.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Strukturmodell ohne dynamische Ablauf- oder Sequenzpfade. Es beschreibt die deklarative Zuordnung und Strukturkonsistenz bei der Modellierung von Festgrößen-Arrays (Größe 5) von der Anwendungsebene auf die Template-basierte C++-Implementierungsebene.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Veranschaulicht die Modellierungsregeln für Arrays mit C++-Standardbibliothek-Bindung (<code>std::array</code>):</p>\n<ul class=\"fig-list\"><li>Ein <code>ApplicationArrayDataType</code> mit <code>fixedSize</code> und <code>maxNumberOfElements = 5</code> korrespondiert mit einem <code>StdCppImplementationDataType</code> der Kategorie <code>ARRAY</code> mit <code>arraySize = 5</code>.\n</li><li>Der Elementtyp des C++-Arrays wird über die Komposition <code>+templateArgument</code> zu <code>CppTemplateArgument</code> und dessen Assoziation <code>+templateType</code> auf einen Standard-Implementierungsdatentyp (<code>uint16_t</code>) modelliert.\n</li><li>Das <code>DataTypeMap</code>-Element verbindet beide Repräsentationen eindeutig für Code-Generatoren und Modellvalidierungswerkzeuge.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-d51dfd685e9cba57", "to": "FIG-06cebc379baf7e0a", "fr": "R18-03_R1.4.0", "tr": "R18-10-1", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li>Instanz <code>ArrayLinearImpl</code>: Typ von <code>CppImplementationDataType</code> zu <code>StdCppImplementationDataType</code> geändert.\n</li><li>Instanz <code>uint16</code>: Umbenannt zu <code>uint16_t</code> und Typ von <code>CppImplementationDataType</code> zu <code>StdCppImplementationDataType</code> geändert.\n</li><li>Instanz <code>:CppTemplateArgument</code>: Attribut <code>anonymous = True</code> entfernt (<code>isVariadicTemplate = False</code> bleibt erhalten).\n</li><li>Instanz <code>DataTypeMapping</code>: Leerzeichen vor Doppelpunkt entfernt (<code>DataTypeMapping: DataTypeMap</code>).\n</li></ul>"}, {"from": "FIG-06cebc379baf7e0a", "to": "FIG-43a72dca760c910c", "fr": "R18-10_R4.4.0_R1.5.0", "tr": "R19-03", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li>Instanz <code>:CppTemplateArgument</code>: Attribut <code>isVariadicTemplate = False</code> entfernt (Klassenrumpf ist nun leer).\n</li></ul>"}, {"from": "FIG-43a72dca760c910c", "to": "FIG-802884da0f61df18", "fr": "R19-11", "tr": "R20-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-802884da0f61df18", "to": "FIG-5d79190f57ee2510", "fr": "R20-11", "tr": "R21-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-5d79190f57ee2510", "to": "FIG-3589afe62107d44a", "fr": "R21-11", "tr": "R22-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
